259:   /**
260:    * Apply a custom transform to this promise.
261:    * <p>
262:    * This method is the basis for the standard operations of this interface, such as {@link #map(Function)}.
263:    * The following is a non generic implementation of a map that converts the value to upper case.
264:    * <pre class="java">{@code
265:    * import ratpack.test.exec.ExecHarness;
266:    * import ratpack.exec.ExecResult;
267:    * import ratpack.exec.Promise;
268:    *
269:    * import static org.junit.Assert.assertEquals;
270:    *
271:    * public class Example {
272:    *   public static void main(String... args) throws Exception {
273:    *     ExecResult<String> result = ExecHarness.yieldSingle(c ->
274:    *       Promise.value("foo")
275:    *         .transform(up -> down ->
276:    *           up.connect(down.<String>onSuccess(value -> {
277:    *             try {
278:    *               down.success(value.toUpperCase());
279:    *             } catch (Throwable e) {
280:    *               down.error(e);
281:    *             }
282:    *           }))
283:    *         )
284:    *     );
285:    *
286:    *     assertEquals("FOO", result.getValue());
287:    *   }
288:    * }
289:    * }</pre>
290:    * <p>
291:    * The “upstreamTransformer” function takes an upstream data source, and returns another upstream that wraps it.
292:    * It is typical for the returned upstream to invoke the {@link Upstream#connect(Downstream)} method of the given upstream during its connect method.
293:    * <p>
294:    * For more examples of transform implementations, please see the implementations of the methods of this interface.
295:    *
296:    * @param upstreamTransformer a function that returns a new upstream, typically wrapping the given upstream argument
297:    * @param <O> the type of item emitted by the transformed upstream
298:    * @return a new promise
299:    */
300:   <O> Promise<O> transform(Function<? super Upstream<? extends T>, ? extends Upstream<O>> upstreamTransformer);
301: 
302:   /**
303:    * Specifies the action to take if the an error occurs trying to produce the promised value, that the given predicate applies to.
304:    * <p>
305:    * If the given action throws an exception, the original exception will be rethrown with the exception thrown
306:    * by the action added to the suppressed exceptions list.
307:    *
308:    * @param predicate the predicate to test against the error
309:    * @param errorHandler the action to take if an error occurs
310:    * @return A promise for the successful result
311:    * @since 1.1
312:    */
313:   default Promise<T> onError(Predicate<? super Throwable> predicate, Action<? super Throwable> errorHandler) {
314:     return transform(up -> down ->
315:       up.connect(down.onError(throwable -> {
316:         if (predicate.apply(throwable)) {
317:           try {
318:             errorHandler.execute(throwable);
319:           } catch (Throwable e) {
320:             if (e != throwable) {
321:               e.addSuppressed(throwable);
322:             }
323:             down.error(e);
324:             return;
325:           }
326:           down.complete();
327:         } else {
328:           down.error(throwable);
329:         }
330:       }))
331:     );
332:   }
333: 
334:   /**
335:    * Specifies the action to take if the an error of the given type occurs trying to produce the promised value.
336:    *
337:    * <pre class="java">{@code
338:    * import ratpack.http.TypedData;
339:    * import ratpack.test.embed.EmbeddedApp;
340:    *
341:    * import static org.junit.Assert.assertEquals;
342:    *
343:    * public class Example {
344:    *   public static void main(String... args) throws Exception {
345:    *     EmbeddedApp.fromHandler(ctx ->
346:    *         ctx.getRequest().getBody()
347:    *           .map(TypedData::getText)
348:    *           .map(t -> {
349:    *             if (t.equals("1")) {
350:    *               throw new IllegalArgumentException("validation error!");
351:    *             } else {
352:    *               throw new RuntimeException("some other error!");
353:    *             }
354:    *           })
355:    *           .onError(IllegalArgumentException.class, e -> ctx.render("the value is invalid"))
356:    *           .onError(e -> ctx.render("unknown error: " + e.getMessage()))
357:    *           .then(t -> ctx.render("ok"))
358:    *     ).test(httpClient -> {
359:    *       assertEquals(httpClient.requestSpec(r -> r.getBody().text("0")).postText(), "unknown error: some other error!");
360:    *       assertEquals(httpClient.requestSpec(r -> r.getBody().text("1")).postText(), "the value is invalid");
361:    *     });
362:    *   }
363:    * }
364:    * }</pre>
365:    * <p>
366:    * If the given action throws an exception, the original exception will be rethrown with the exception thrown
367:    * by the action added to the suppressed exceptions list.
368:    *
369:    * @param errorType the type of exception to handle with the given action
370:    * @param errorHandler the action to take if an error occurs
371:    * @param <E> the type of exception to handle with the given action
372:    * @return A promise for the successful result
373:    * @since 1.1
374:    */
375:   default <E extends Throwable> Promise<T> onError(Class<E> errorType, Action<? super E> errorHandler) {
376:     return onError(errorType::isInstance, t -> errorHandler.execute(errorType.cast(t)));
377:   }
378: 
379:   /**
380:    * Specifies the action to take if the an error occurs trying to produce the promised value.
381:    * <p>
382:    * If the given action throws an exception, the original exception will be rethrown with the exception thrown
383:    * by the action added to the suppressed exceptions list.
384:    *
385:    * @param errorHandler the action to take if an error occurs
386:    * @return A promise for the successful result
387:    */
388:   default Promise<T> onError(Action<? super Throwable> errorHandler) {
389:     return onError(Predicate.TRUE, errorHandler);
390:   }
