1292:    *       Promise<Long> cached = uncached.cache();
1293:    *
1294:    *       cached.then(i -> assertEquals(3l, i.longValue()));
1295:    *       cached.then(i -> assertEquals(3l, i.longValue()));
1296:    *
1297:    *       uncached.then(i -> assertEquals(4l, i.longValue()));
1298:    *       cached.then(i -> assertEquals(3l, i.longValue()));
