1350:   /**
1351:    * Caches the promise result and provides it to all future subscribers, if it satisfies the predicate.
1352:    * <p>
1353:    * This method is typically used when wanting to cache a failure result or a success result.
1354:    * Moreover, the error throwable or success value can be inspected to determine whether it should be cached.
1355:    * <p>
1356:    * A cached promise is fully threadsafe and and can be subscribed to concurrently.
1357:    * While there is no cached value, yielding the upstream value is serialised.
1358:    * That is, one value is requested at a time regardless of concurrent subscription.
1359:    * If a cache-able value is received, all pending subscribers will received the cache-able value.
1360:    * If a received value is not cache-able the corresponding subscriber will receive the value,
1361:    * and the upstream promise will be subscribed to again on behalf of the next subscriber.
1362:    *
1363:    * <pre class="java">{@code
1364:    * import ratpack.exec.ExecResult;
1365:    * import ratpack.exec.Promise;
1366:    * import ratpack.test.exec.ExecHarness;
1367:    *
1368:    * import java.util.ArrayList;
1369:    * import java.util.List;
1370:    * import java.util.concurrent.atomic.AtomicInteger;
1371:    *
1372:    * import static org.junit.Assert.assertEquals;
1373:    *
1374:    * public class Example {
1375:    *
1376:    *   public static void main(String... args) throws Exception {
1377:    *     List<ExecResult<Integer>> results = new ArrayList<>();
1378:    *     AtomicInteger counter = new AtomicInteger();
1379:    *     Promise<Integer> promise = Promise.sync(() -> {
1380:    *       int i = counter.getAndIncrement();
1381:    *       if (i < 2) {
1382:    *         return i;
1383:    *       } else if (i == 2) {
1384:    *         throw new Exception(Integer.toString(i));
1385:    *       } else if (i == 3) {
1386:    *         throw new RuntimeException(Integer.toString(i));
1387:    *       } else {
1388:    *         throw new IllegalStateException(Integer.toString(i));
1389:    *       }
1390:    *     });
1391:    *
1392:    *     Promise<Integer> cachedPromise = promise.cacheResultIf(r ->
1393:    *       (r.isError() && r.getThrowable().getClass() == RuntimeException.class)
1394:    *         || (r.isSuccess() && r.getValue() > 10)
1395:    *     );
1396:    *
1397:    *     ExecHarness.runSingle(e -> {
1398:    *       for (int i = 0; i < 6; i++) {
1399:    *         cachedPromise.result(results::add);
1400:    *       }
1401:    *     });
1402:    *
1403:    *     assertEquals(results.get(0).getValueOrThrow(), Integer.valueOf(0));
1404:    *     assertEquals(results.get(1).getValueOrThrow(), Integer.valueOf(1));
1405:    *     assertEquals(results.get(2).getThrowable().getClass(), Exception.class);
1406:    *     assertEquals(results.get(3).getThrowable().getClass(), RuntimeException.class);
1407:    *
1408:    *     // value is now cached
1409:    *     assertEquals(results.get(4).getThrowable().getClass(), RuntimeException.class);
1410:    *     assertEquals(results.get(5).getThrowable().getClass(), RuntimeException.class);
1411:    *   }
1412:    * }
1413:    * }</pre>
1414:    *
1415:    * <p>
1416:    * Note, the cached value never expires.
1417:    * If you wish to cache a value only for a certain amount of time,
1418:    * use a general caching tool such as Guava's {@link LoadingCache}.
1419:    *
1420:    * <pre class="java">{@code
1421:    * import com.google.common.cache.CacheBuilder;
1422:    * import com.google.common.cache.CacheLoader;
1423:    * import com.google.common.cache.LoadingCache;
1424:    * import ratpack.exec.ExecResult;
1425:    * import ratpack.exec.Promise;
1426:    * import ratpack.test.exec.ExecHarness;
1427:    *
1428:    * import java.util.ArrayList;
1429:    * import java.util.List;
1430:    * import java.util.concurrent.TimeUnit;
1431:    * import java.util.concurrent.atomic.AtomicInteger;
1432:    *
1433:    * import static org.junit.Assert.assertEquals;
1434:    *
1435:    * public class Example {
1436:    *
1437:    *   public static void main(String... args) throws Exception {
1438:    *     List<ExecResult<Integer>> results = new ArrayList<>();
1439:    *     AtomicInteger counter = new AtomicInteger();
1440:    *     Promise<Integer> promise = Promise.sync(counter::getAndIncrement);
1441:    *
1442:    *     LoadingCache<String, Promise<Integer>> cache = CacheBuilder.newBuilder()
1443:    *       .expireAfterWrite(2, TimeUnit.SECONDS)
1444:    *       .build(new CacheLoader<String, Promise<Integer>>() {
1445:    *         public Promise<Integer> load(String key) throws Exception {
1446:    *           return promise.cacheResultIf(i -> i.isSuccess() && i.getValue() > 1);
1447:    *         }
1448:    *       });
1449:    *
1450:    *     ExecHarness.runSingle(e -> {
1451:    *       for (int i = 0; i < 4; i++) {
1452:    *         cache.get("key").result(results::add);
1453:    *       }
1454:    *
1455:    *       // let the cache entry expire
1456:    *       Thread.sleep(2000);
1457:    *
1458:    *       for (int i = 0; i < 2; i++) {
1459:    *         cache.get("key").result(results::add);
1460:    *       }
1461:    *     });
1462:    *
1463:    *     assertEquals(results.get(0).getValueOrThrow(), Integer.valueOf(0));
1464:    *     assertEquals(results.get(1).getValueOrThrow(), Integer.valueOf(1));
1465:    *     assertEquals(results.get(2).getValueOrThrow(), Integer.valueOf(2));
1466:    *     assertEquals(results.get(3).getValueOrThrow(), Integer.valueOf(2));
1467:    *
1468:    *     // cache entry has expired
1469:    *
1470:    *     assertEquals(results.get(4).getValueOrThrow(), Integer.valueOf(3));
1471:    *     assertEquals(results.get(5).getValueOrThrow(), Integer.valueOf(3));
1472:    *   }
1473:    * }
1474:    * }</pre>
1475:    *
1476:    * @param shouldCache the test for whether a result is cacheable
1477:    * @return a caching promise
1478:    * @since 1.4
1479:    */
1480:   default Promise<T> cacheResultIf(Predicate<? super ExecResult<T>> shouldCache) {
1481:     return transform(up -> new CachingUpstream<>(up, shouldCache));
1482:   }
