1683:    * import ratpack.exec.Promise;
1684:    * import ratpack.test.exec.ExecHarness;
1685:    *
1686:    * public class Example {
1687:    *   static class MyResource implements AutoCloseable {
1688:    *     final boolean inError;
1689:    *     boolean closed;
1690:    *
1691:    *     public MyResource(boolean inError) {
1692:    *       this.inError = inError;
1693:    *     }
1694:    *
1695:    *     {@literal @}Override
1696:    *     public void close() {
1697:    *       closed = true;
1698:    *     }
1699:    *   }
1700:    *
1701:    *   static Promise<String> resourceUsingMethod(MyResource resource) {
1702:    *     return Promise.sync(() -> {
1703:    *       if (resource.inError) {
1704:    *         throw new Exception("error!");
1705:    *       } else {
1706:    *         return "ok!";
1707:    *       }
1708:    *     });
1709:    *   }
1710:    *
1711:    *   public static void main(String[] args) throws Exception {
1712:    *     ExecHarness.runSingle(e -> {
1713:    *       MyResource myResource = new MyResource(false);
1714:    *       resourceUsingMethod(myResource)
1715:    *         .close(myResource)
1716:    *         .then(value -> Assert.assertTrue(myResource.closed));
1717:    *     });
1718:    *
1719:    *     ExecHarness.runSingle(e -> {
1720:    *       MyResource myResource = new MyResource(true);
1721:    *       resourceUsingMethod(myResource)
1722:    *         .close(myResource)
1723:    *         .onError(error -> Assert.assertTrue(myResource.closed))
1724:    *         .then(value -> {
1725:    *           throw new UnsupportedOperationException("should not reach here!");
1726:    *         });
