59:     if (config.getRequestMetricGroups() != null) {
60:       for (Map.Entry<String, String> metricGrouping : config.getRequestMetricGroups().entrySet()) {
61:         if (requestPath.matches(metricGrouping.getValue())) {
62:           tagName = metricGrouping.getKey();
63:           break;
64:         }
65:       }
66:     }
67: 
68:     return tagName + "." + requestMethod.toLowerCase() + "-blocking";
69:   }
