27: import ratpack.launch.LaunchConfigBuilder;
28: import ratpack.util.ExceptionUtils;
29: 
30: import java.util.concurrent.CountDownLatch;
31: import java.util.concurrent.TimeUnit;
32: 
33: public class BlockingHttpClient implements AutoCloseable {
34: 
35:   private final LaunchConfig execController;
36: 
37:   public BlockingHttpClient() {
38:     //TODO allow this to be configured
39:     this.execController = LaunchConfigBuilder
40:       .noBaseDir()
41:       .bufferAllocator(UnpooledByteBufAllocator.DEFAULT)
42:       .maxContentLength(Integer.MAX_VALUE)
43:       .build();
44:   }
45: 
46:   public ReceivedResponse request(Action<? super RequestSpec> action) throws Throwable {
47:     final RequestAction requestAction = new RequestAction(execController, action);
48: 
49:     execController.execController().getControl().fork(new Action<Execution>() {
50:       @Override
51:       public void execute(Execution execution) throws Exception {
52:         requestAction.execute(execution);
53:       }
54:     }, new Action<Throwable>() {
55:       @Override
56:       public void execute(Throwable throwable) throws Exception {
57:         requestAction.setResult(Result.<ReceivedResponse>failure(throwable));
58:       }
59:     });
60: 
61:     try {
62:       // TODO - make this configurable
63:       // TODO - improve this exception (better type and add info about the request)
64:       if (!requestAction.latch.await(60, TimeUnit.SECONDS)) {
65:         throw new IllegalStateException("Timeout");
66:       }
67:     } catch (InterruptedException e) {
68:       throw ExceptionUtils.uncheck(e);
69:     }
70: 
71:     return requestAction.result.getValueOrThrow();
72:   }
73: 
74:   private static class RequestAction implements Action<Execution> {
75:     private final LaunchConfig execController;
76:     private final Action<? super RequestSpec> action;
77: 
78:     private final CountDownLatch latch = new CountDownLatch(1);
79:     private Result<ReceivedResponse> result;
80: 
81:     private RequestAction(LaunchConfig launchConfig, Action<? super RequestSpec> action) {
82:       this.execController = launchConfig;
83:       this.action = action;
84:     }
85: 
86:     private void setResult(Result<ReceivedResponse> result) {
87:       this.result = result;
88:       latch.countDown();
89:     }
90: 
91:     @Override
92:     public void execute(Execution execution) throws Exception {
93:       HttpClients.httpClient(execController).request(action)
94:         .then(new Action<ReceivedResponse>() {
95:           @Override
96:           public void execute(ReceivedResponse response) throws Exception {
97:             response.getBody().getBuffer().retain();
98:             setResult(Result.success(response));
99:           }
100:         });
101:     }
102:   }
103: 
104:   @Override
105:   public void close() {
106:     execController.execController().close();
107:   }
108: }
