71: 
72:     // There are definitely concurrency bugs in here around timing out
73:     // ideally we should prevent the stat from changing after a timeout occurs
74: 
75:     this.headers = new DelegatingHeaders(responseHeaders);
76:     this.status = status;
77: 
78:     final CountDownLatch latch = new CountDownLatch(1);
79: 
80:     final StreamTransmitter streamTransmitter = new DefaultStreamTransmitter(null, null, null); //TODO: what test support is required here?
81: 
82:     final EventController<RequestOutcome> eventController = new DefaultEventController<>();
83: 
84:     final FileHttpTransmitter fileHttpTransmitter = new FileHttpTransmitter() {
85:       @Override
86:       public void transmit(ExecControl execContext, BasicFileAttributes basicFileAttributes, Path file) {
87:         sentFile = file;
88:         eventController.fire(new DefaultRequestOutcome(request, new DefaultSentResponse(headers, status), System.currentTimeMillis()));
89:         latch.countDown();
90:       }
91:     };
92: 
93:     final Action<ByteBuf> committer = new Action<ByteBuf>() {
94:       public void execute(ByteBuf byteBuf) throws Exception {
95:         sentResponse = true;
96:         body = new byte[byteBuf.readableBytes()];
97:         byteBuf.readBytes(body);
98:         byteBuf.release();
99:         eventController.fire(new DefaultRequestOutcome(request, new DefaultSentResponse(headers, status), System.currentTimeMillis()));
100:         latch.countDown();
101:       }
102:     };
103: 
104:     final Handler next = new Handler() {
105:       public void handle(Context context) {
106:         calledNext = true;
107:         latch.countDown();
108:       }
109:     };
110: 
111:     final BindAddress bindAddress = new BindAddress() {
112:       @Override
113:       public String getHost() {
114:         return "localhost";
115:       }
116: 
117:       @Override
118:       public int getPort() {
119:         return 5050;
120:       }
121:     };
122: 
