50:   @Override
51:   protected void startUp() throws Exception {
52:     ServerBootstrap bootstrap = new ServerBootstrap();
53:     group = new NioEventLoopGroup(launchConfig.getMainThreads(), new DefaultThreadFactory("ratpack-group", Thread.MAX_PRIORITY));
54: 
55:     bootstrap
56:       .group(group)
57:       .channel(NioServerSocketChannel.class)
58:       .childHandler(channelInitializer)
59:       .childOption(ChannelOption.ALLOCATOR, launchConfig.getBufferAllocator())
60:       .childOption(ChannelOption.TCP_NODELAY, true)
61:       .option(ChannelOption.SO_REUSEADDR, true)
62:       .option(ChannelOption.SO_BACKLOG, 1024)
63:       .option(ChannelOption.ALLOCATOR, launchConfig.getBufferAllocator());
64: 
65:     try {
66:       channel = bootstrap.bind(buildSocketAddress()).sync().channel();
67:     } catch (Exception e) {
68:       partialShutdown();
69:       throw e;
70:     }
71:     boundAddress = (InetSocketAddress) channel.localAddress();
72: 
73:     if (logger.isLoggable(Level.INFO)) {
74:       logger.info(String.format("Ratpack started for http://%s:%s", getBindHost(), getBindPort()));
75:     }
