884:   /**
885:    * Applies the given function to {@code this} and returns the result.
886:    * <p>
887:    * This method can be useful when needing to convert a promise to another type as it facilitates doing so without breaking the “code flow”.
888:    * For example, this can be used when integrating with RxJava.
889:    * <pre class="java">{@code
890:    * import ratpack.rx.RxRatpack;
891:    * import ratpack.exec.Promise;
892:    * import ratpack.test.exec.ExecHarness;
893:    *
894:    * import java.util.Arrays;
895:    * import java.util.LinkedList;
896:    * import java.util.List;
897:    *
898:    * import static org.junit.Assert.assertEquals;
899:    *
900:    * public class Example {
901:    *   private static final List<String> LOG = new LinkedList<>();
902:    *
903:    *   public static void main(String... args) throws Exception {
904:    *     ExecHarness.runSingle(e ->
905:    *         Promise.value("foo")
906:    *           .to(RxRatpack::observe)
907:    *           .doOnNext(i -> LOG.add("doOnNext"))
908:    *           .subscribe(LOG::add)
909:    *     );
910:    *
911:    *     assertEquals(Arrays.asList("doOnNext", "foo"), LOG);
912:    *   }
913:    * }
914:    * }</pre>
915:    * <p>
916:    * The given function is executed immediately.
917:    * <p>
918:    * This method should only be used when converting a promise to another type.
919:    * See {@link #apply(Function)} for applying custom promise operators.
920:    *
921:    * @param function the promise conversion function
922:    * @param <O> the type the promise will be converted to
923:    * @return the output of the given function
924:    * @throws Exception any thrown by the given function
925:    */
926:   default <O> O to(Function<? super Promise<T>, ? extends O> function) throws Exception {
927:     return function.apply(this);
