1257:    * <p>
1258:    * Note that the {@link Throttle} instance given defines the actual throttling semantics.
1259:    * <pre class="java">{@code
1260:    * import ratpack.exec.Throttle;
1261:    * import ratpack.exec.Promise;
1262:    * import ratpack.exec.Execution;
1263:    * import ratpack.test.exec.ExecHarness;
1264:    * import ratpack.exec.ExecResult;
1265:    *
1266:    * import java.util.concurrent.atomic.AtomicInteger;
1267:    *
1268:    * import static org.junit.Assert.assertTrue;
1269:    *
1270:    * public class Example {
1271:    *   public static void main(String... args) throws Exception {
1272:    *     int numJobs = 1000;
1273:    *     int maxAtOnce = 10;
1274:    *
1275:    *     ExecResult<Integer> result = ExecHarness.yieldSingle(exec -> {
1276:    *       AtomicInteger maxConcurrent = new AtomicInteger();
1277:    *       AtomicInteger active = new AtomicInteger();
1278:    *       AtomicInteger done = new AtomicInteger();
1279:    *
1280:    *       Throttle throttle = Throttle.ofSize(maxAtOnce);
1281:    *
1282:    *       // Launch numJobs forked executions, and return the maximum number that were executing at any given time
1283:    *       return Promise.async(downstream -> {
1284:    *         for (int i = 0; i < numJobs; i++) {
1285:    *           Execution.fork().start(forkedExec ->
1286:    *             Promise.sync(() -> {
1287:    *               int activeNow = active.incrementAndGet();
1288:    *               int maxConcurrentVal = maxConcurrent.updateAndGet(m -> Math.max(m, activeNow));
1289:    *               active.decrementAndGet();
1290:    *               return maxConcurrentVal;
1291:    *             })
1292:    *             .throttled(throttle) // limit concurrency
1293:    *             .then(max -> {
1294:    *               if (done.incrementAndGet() == numJobs) {
1295:    *                 downstream.success(max);
1296:    *               }
1297:    *             })
1298:    *           );
1299:    *         }
1300:    *       });
1301:    *     });
1302:    *
1303:    *     assertTrue(result.getValue() <= maxAtOnce);
