', execution_details='Use IntelliJ Rename refactoring on the build() method in the ByAcceptsResponder interface to change its name to respond(), updating all implementors and call sites.', refactoring_type=<SupportedRefactorings.RENAME: 'rename'>, file_path='ratpack-core/src/main/java/org/ratpackframework/handling/internal/DefaultByAcceptsResponder.java'), PlanningStep(reason='The DefaultByAcceptsResponder implementation overrides build(), performing I/O; rename method to match the interface change.', final_code='package org.ratpackframework.handling.internal;

import io.netty.handler.codec.http.HttpHeaders;
import org.ratpackframework.handling.Context;
import org.ratpackframework.handling.ByAcceptsResponder;
import org.ratpackframework.http.internal.MimeParse;

import java.util.*;

public class DefaultByAcceptsResponder implements ByAcceptsResponder {

  private final Map<String, Runnable> map = new LinkedHashMap<String, Runnable>(3);
  private String first;
  private final Context context;

  public DefaultByAcceptsResponder(Context context) {
    this.context = context;
  }

  public ByAcceptsResponder type(String mimeType, Runnable runnable) {
    if (mimeType == null) {
      throw new IllegalArgumentException("mimeType cannot be null");
    }

    String trimmed = mimeType.trim();
    if (trimmed.isEmpty()) {
      throw new IllegalArgumentException("mimeType cannot be a blank string");
    }

    if (first == null) {
      first = trimmed;
    }
    map.put(trimmed, runnable);
    return this;
  }

  public ByAcceptsResponder plainText(Runnable runnable) {
    return type("text/plain", runnable);
  }

  public ByAcceptsResponder html(Runnable runnable) {
    return type("text/html", runnable);
  }

  public ByAcceptsResponder json(Runnable runnable) {
    return type("application/json", runnable);
  }

  public ByAcceptsResponder xml(Runnable runnable) {
    return type("application/xml", runnable);
  }

  @Override
  public void respond() {
    if (first == null) {
      context.clientError(406);
      return;
    }

    List<String> types = new ArrayList<String>(map.keySet());
    Collections.reverse(types);
    String winner = first;

    String acceptHeader = context.getRequest().getHeader(HttpHeaders.Names.ACCEPT);
    if (acceptHeader != null && !acceptHeader.isEmpty()) {
      winner = MimeParse.bestMatch(types, acceptHeader);
    }

    if (winner == null || winner.isEmpty()) {
      context.clientError(406);
    } else {
      context.getResponse().setHeader(HttpHeaders.Names.CONTENT_TYPE, winner);
      Runnable runnable = map.get(winner);
      runnable.run();
    }
  }

}
